(() => {
  const ids=['openCodeMapModalBtn','openInspectorModalBtn','sessionCodeMapBtn','sessionTaskLogBtn','sessionPinRuleBtn'];
  const out=[];
  for (const id of ids) {
    const e=document.getElementById(id);
    if(!e) continue;
    const walk=[];
    e.querySelectorAll('*').forEach(el=>{const c=getComputedStyle(el); walk.push({tag:el.tagName, id:el.id, cls:el.className, text:el.textContent.trim().slice(0,20), color:c.color, bg:c.backgroundColor, fontSize:c.fontSize});});
    const c=getComputedStyle(e);
    out.push({id, color:c.color, html:e.innerHTML, children:walk});
  }
  return out;
})()

