.xp-dialog-body .btn:hover,
.xp-cpl-body .btn:hover,
.xp-taskmanager-window .btn:hover {
  background: linear-gradient(180deg, #ffffff 0%, #fff8dc 35%, #ffe7a3 100%) !important;
  border-color: #e5a500 !important;
}
