}
.xp-window .btn:disabled,
.xp-dialog-body .btn:disabled,
.xp-cpl-body .btn:disabled,
.xp-taskmanager-window .btn:disabled {
  color: #8a8a8a !important;
  background: #ece9d8 !important;
}
.xp-window .btn-primary,
.xp-dialog-body .btn-primary,
.xp-cpl-body .btn-primary,
.xp-taskmanager-window .btn-primary {
  background: linear-gradient(180deg, #5ba9ff 0%, #1173f0 48%, #0053ee 100%) !important;
  border: 1px solid #003c74 !important;
  color: #ffffff !important;
  font-weight: 700 !important;
}
.xp-window .btn-primary:hover,
.xp-dialog-body .btn-primary:hover,
.xp-cpl-body .btn-primary:hover,
.xp-taskmanager-window .btn-primary:hover {
  background: linear-gradient(180deg, #7dbcff 0%, #2f8cff 48%, #0b62f4 100%) !important;
  border-color: #e5a500 !important;
}

