  const lum = rgb => (0.2126*rgb[0]+0.7152*rgb[1]+0.0722*rgb[2]);
  const bgOf = el => { let n=el; while(n && n!==document.documentElement){ const cs=getComputedStyle(n); const rgba=cs.backgroundColor; if(rgba && !/rgba\\(0,\\s*0,\\s*0,\\s*0\\)/.test(rgba)) return {color:parse(rgba), src:n.className||n.tagName}; if(cs.backgroundImage && cs.backgroundImage!=='none') return {color:parse(cs.backgroundImage), src:(n.className||n.tagName)+' (image)'}; n=n.parentElement; } return {color:[255,255,255], src:'root'}; };
  const out=[];
  document.querySelectorAll('button, input[type=button], input[type=submit], [role=button]').forEach(b=>{
    const r=b.getBoundingClientRect(); const cs=getComputedStyle(b);
    if(r.width<2||r.height<2||cs.visibility==='hidden'||cs.display==='none') return;
    const fg=parse(cs.color)||[0,0,0]; const bg=bgOf(b);
    if(!bg.color) return;
    const fl=lum(fg), bl=lum(bg.color);
    const contrast=(Math.max(fl,bl)+5)/(Math.min(fl,bl)+5);
    if(contrast<2.4 || (bl<60 && fl<120)) {
      out.push({tag:b.tagName, id:b.id, cls:(b.className||'').toString().slice(0,50), text:(b.textContent||b.value||'').trim().slice(0,30), fg:cs.color, bg:bg.src, contrast:+contrast.toFixed(2), rect:{x:Math.round(r.x),y:Math.round(r.y),w:Math.round(r.width),h:Math.round(r.height)}});
    }
  });
  return out;
})()` });
