#define SQL3_MEDIUM_V2
// SQL V3 Atmosphere V2: participating media as relations.
//
//   layers   (height fog, ground mist, moving banks)       4 rows each: _SQL3MediumLayers
//   volumes  (fog, smoke, fire, steam: box/ellipsoid/cyl)   8 rows each: _SQL3MediumVolumes
//   light    (world cell -> light from the local lights and fires that reach it, the mean direction
//            it comes from and the sun's transmittance through the media): _SQL3MediumLight/Dir
//
// The light relation is the expensive one (shadow rays to every light, marches through the medium)
// and it is keyed like a database row: (world cell, the state of every light that reaches the cell,
// the media overlapping it). A cell whose key has not changed is not evaluated again; its stored
// row is inferred to still hold (up to a maximum age, for animated occluders). Froxels, water and
// any other shader join it with one trilinear lookup. Nothing here depends on URP's Lighting.hlsl,
// so pixel shaders and compute kernels share it.
StructuredBuffer<float4> _SQL3MediumLayers;
StructuredBuffer<float4> _SQL3MediumVolumes;
float4 _SQL3MediumCounts;     // x: layers, y: volumes, z: time (s), w: enabled
Texture3D<float4> _SQL3MediumLight;     // rgb: light from local lights and fires (URP light units), a: 1 evaluated
Texture3D<float4> _SQL3MediumLightDir;  // xyz: luminance-weighted mean direction toward those lights, w: sun transmittance
float4 _SQL3MediumCacheMin;   // xyz: world minimum of the window, w: cell size (m)
float4 _SQL3MediumCacheDims;  // xyz: cells, w: valid
float4 _SQL3MediumScales;     // x: local light scattering, y: underwater god rays, z: fire emission scale, w: unused
float _SQL3DistortActive;     // >0.5 when fire or shockwave distortion is active
SamplerState sql3_medium_linear_repeat_sampler;

#define SQL3_MEDIUM_LAYER_ROWS 4
#define SQL3_MEDIUM_VOLUME_ROWS 8
#define SQL3_MEDIUM_FIRE 2
#define SQL3_MEDIUM_EXPLOSION 5

struct SQL3Medium
{
    float extinction;    // 1/m
    float3 scattering;   // 1/m (extinction x albedo)
    float anisotropy;    // scattering-weighted HG g
    float3 emission;     // radiance per metre (fire)
};
bool SQL3MediumEnabled(){return _SQL3MediumCounts.w>.5;}

// ---- Procedural noise (no texture dependencies: works with or without the cloud simulation) ----
float SQL3MediumHash(float3 p)
{
    p=frac(p*.3183099+.1);p*=17;
    return frac(p.x*p.y*p.z*(p.x+p.y+p.z));
}
float SQL3MediumValueNoise(float3 x)
{
    float3 i=floor(x),f=frac(x);f=f*f*(3-2*f);
    return lerp(lerp(lerp(SQL3MediumHash(i),SQL3MediumHash(i+float3(1,0,0)),f.x),
                     lerp(SQL3MediumHash(i+float3(0,1,0)),SQL3MediumHash(i+float3(1,1,0)),f.x),f.y),
                lerp(lerp(SQL3MediumHash(i+float3(0,0,1)),SQL3MediumHash(i+float3(1,0,1)),f.x),
                     lerp(SQL3MediumHash(i+float3(0,1,1)),SQL3MediumHash(i+float3(1,1,1)),f.x),f.y),f.z);
}
// Three octaves, 0..1, mean ~0.5. cheap: one octave (light marches).
float SQL3MediumNoise(float3 p,bool cheap)
{
    float n=SQL3MediumValueNoise(p);
    if(cheap)return n;
    return n*.57+SQL3MediumValueNoise(p*2.03+17.1)*.29+SQL3MediumValueNoise(p*4.11-5.3)*.14;
}

// ---- Layers: height fog with an optional top and drifting noise ----
// rows: (density, height falloff, base height, top height) (albedo, g) (velocity, noise frequency)
//       (noise strength, top fade, 0, 0)
float SQL3MediumLayerDensity(int layer,float3 p,bool cheap,out float3 albedo,out float g)
{
