    if(d.x>0 && density>0)
    {
        float n=SQL3MediumNoise((p-c.xyz*_SQL3MediumCounts.z)*c.w,cheap);
        density*=max(lerp(1,n*2,d.x),0);
    }
    return density;
}

// ---- Volumes ----
// rows: (centre, shape) (half extents, edge softness) (right axis, density) (up axis, kind)
//       (albedo, g) (velocity, noise frequency) (emission rgb, noise strength)
//       (bounding radius, rise, light range, light intensity)
