    float3 extent=max(r1.xyz,1e-3);
    height01=saturate(local.y/extent.y*.5+.5);
    float sd;
    int shape=(int)r0.w;
    if(shape==0){float3 q=abs(local)-extent;sd=length(max(q,0))+min(max(q.x,max(q.y,q.z)),0);}
