    return saturate(-sd/max(r1.w,.01));
}
void SQL3MediumAddVolume(int v,float3 p,bool cheap,inout SQL3Medium m)
{
    float4 r0=_SQL3MediumVolumes[v*8],r7=_SQL3MediumVolumes[v*8+7];
    float3 d=p-r0.xyz;
    if(dot(d,d)>r7.x*r7.x)return;
    float4 r3=_SQL3MediumVolumes[v*8+3];
    int kind=(int)r3.w;
    if(kind==SQL3_MEDIUM_EXPLOSION)
    {
        float radius=r7.y;
        if(radius<=0.01)return;
        float4 r1=_SQL3MediumVolumes[v*8+1],r2=_SQL3MediumVolumes[v*8+2],r4=_SQL3MediumVolumes[v*8+4],r5=_SQL3MediumVolumes[v*8+5],r6=_SQL3MediumVolumes[v*8+6];
        float r=length(d);
        float ring=saturate(1.0-abs(r-radius)/max(r1.w,.05));
        if(ring<=0)return;
        float n=r6.w>0 ? SQL3MediumNoise((p-r5.xyz*_SQL3MediumCounts.z)*r5.w,cheap) : .5;
        float density=r2.w*ring*max(lerp(1,n*2,r6.w),0);
        if(density<=0)return;
        m.extinction+=density;
        float3 scattering=density*r4.rgb;
        m.anisotropy+=r4.a*dot(scattering,float3(.2126,.7152,.0722));
        m.scattering+=scattering;
        m.emission+=r6.rgb*ring*saturate(n*1.7)*_SQL3MediumScales.z;
        return;
    }
    float height01;
    float shape=SQL3MediumVolumeShape(v,p,height01);
    if(shape<=0)return;
    float4 r2=_SQL3MediumVolumes[v*8+2],r4=_SQL3MediumVolumes[v*8+4],r5=_SQL3MediumVolumes[v*8+5],r6=_SQL3MediumVolumes[v*8+6];
    // Rising media thin out toward the top (fire tongues, smoke plumes widening and fading).
    float profile=lerp(1,1-height01,r7.y);
    float n=r6.w>0 ? SQL3MediumNoise((p-r5.xyz*_SQL3MediumCounts.z)*r5.w,cheap) : .5;
    float density=r2.w*shape*profile*max(lerp(1,n*2,r6.w),0);
    if(density<=0)return;
    m.extinction+=density;
    float3 scattering=density*r4.rgb;
    float weight=dot(scattering,float3(.2126,.7152,.0722));
    m.anisotropy+=r4.a*weight;
    m.scattering+=scattering;
    // Fire: emission concentrated where the noise is dense (flames), fading with height.
    if(kind==SQL3_MEDIUM_FIRE)m.emission+=r6.rgb*shape*profile*profile*saturate(n*n*2.5)*_SQL3MediumScales.z;
}

