const res = await tools.browser.evaluate({
  tabID,
  script: `(async () => {
    const boot = document.getElementById('xpBootSequenceOverlay');
    if (boot && getComputedStyle(boot).display !== 'none') return { err: 'boot overlay still up' };
    // 1. Create a disposable session via the New Session modal
    const btn = document.getElementById('wlmMainNewSessionBtn');
    if (!btn) return { err: 'no new session btn' };
    btn.click();
    await new Promise(r => setTimeout(r, 200));
    document.getElementById('newSessionName').value = 'delete_flow_test';
    document.getElementById('newSessionDesc').value = 'temp';
    document.getElementById('createSessionBtn').click();
    await new Promise(r => setTimeout(r, 1500));
    // 2. Find its row and right-click it
    const row = [...document.querySelectorAll('.wlm-contact-banner-row')].find(r => r.textContent.includes('delete_flow_test'));
    if (!row) return { err: 'row not found after create', rows: [...document.querySelectorAll('.wlm-contact-banner-row')].map(r => r.textContent.trim().slice(0, 20)) };
    const r = row.getBoundingClientRect();
    row.dispatchEvent(new MouseEvent('contextmenu', { bubbles: true, cancelable: true, clientX: r.left + 60, clientY: r.top + 10, button: 2 }));
    const menu = document.getElementById('wlmSessionCtxMenu');
    if (!menu) return { err: 'context menu did not open' };
    // 3. Arm
    menu.querySelector('#wlmCtxDelete').click();
    const armed = !!document.getElementById('wlmSessionCtxMenu');
    const armedTxt = armed ? document.getElementById('wlmSessionCtxMenu').querySelector('#wlmCtxDelete').textContent.trim() : null;
    // 4. Confirm
    const menu2 = document.getElementById('wlmSessionCtxMenu');
    if (!menu2) return { err: 'menu vanished after arm', armedTxt };
    menu2.querySelector('#wlmCtxDelete').click();
    await new Promise(r => setTimeout(r, 1500));
    const data = await (await fetch('/api/iba/sessions')).json();
    return {
      armed, armedTxt,
      removed: !(data.sessions || []).some(s => s.session_id === 'delete_flow_test'),
      active: data.active_session
    };
  })()`
})
const errs = await tools.browser.console({ tabID, level: "error" })
return { res: res.value, errors: (errs.messages || []).slice(-5) }

